/**
 * Bundled seed lessons added without overwriting anything already saved.
 * Titles beginning with "Grammar:" feed the grammar retriever; all entries feed
 * retrieval, reasoning summaries and the word-level training corpus.
 */
export interface ExpansionLesson {
  id: string;
  title: string;
  content: string;
}

export const EXPANDED_LESSONS: ExpansionLesson[] = [
  /* --------------------------- sentence structure -------------------------- */
  { id: "grammar-simple-sentence", title: "Grammar: Simple sentences", content: "A simple sentence contains one independent clause with a subject and a verb. It can be short, such as Birds fly, or include modifiers, such as The small birds fly quickly. A simple sentence is complete even though it has only one clause." },
  { id: "grammar-compound-sentence", title: "Grammar: Compound sentences", content: "A compound sentence joins two or more independent clauses with a coordinating conjunction such as and, but, or or so. Example: I studied hard, and I passed the test. Each clause could stand alone as its own sentence." },
  { id: "grammar-complex-sentence", title: "Grammar: Complex sentences", content: "A complex sentence contains one independent clause and at least one dependent clause. Example: I stayed home because it rained. The dependent clause adds reason, time, condition or contrast and cannot stand alone." },
  { id: "grammar-compound-complex-sentence", title: "Grammar: Compound-complex sentences", content: "A compound-complex sentence has at least two independent clauses and one dependent clause. Example: I finished my work, and I went outside after the rain stopped. Use it when several related ideas need precise connections." },
  { id: "grammar-clauses", title: "Grammar: Clauses", content: "A clause is a group of words with a subject and a verb. An independent clause can stand alone. A dependent clause begins with a subordinator such as because, although or when and needs an independent clause to complete its meaning." },
  { id: "grammar-phrases", title: "Grammar: Phrases", content: "A phrase is a group of words that acts as one part of a sentence but does not contain both a subject and a verb. Examples include in the room, a careful reader and to learn. Phrases add detail without forming a full clause." },
  { id: "grammar-subject-verb-agreement", title: "Grammar: Subject-verb agreement", content: "A verb agrees with its subject in number. A singular subject usually takes a verb ending in s in the present tense, such as She reads. A plural subject uses the base form, such as They read. Phrases between the subject and verb do not change the agreement." },
  { id: "grammar-verb-tenses", title: "Grammar: Verb tenses", content: "Verb tenses place actions and states in time. The simple present describes habits or facts, the simple past describes completed events, and the simple future describes what will happen. Continuous, perfect and perfect continuous forms add detail about duration or completion." },
  { id: "grammar-perfect-tenses", title: "Grammar: Perfect tenses", content: "Perfect tenses use have, has or had with a past participle. The present perfect links past events to now, as in I have finished. The past perfect describes an event before another past event, as in I had eaten before you arrived." },
  { id: "grammar-progressive-tenses", title: "Grammar: Progressive tenses", content: "Progressive tenses use a form of be with an ing verb. They describe actions in progress, such as She is reading or They were working. Stative verbs such as know and believe are less often used in progressive forms." },
  { id: "grammar-active-passive", title: "Grammar: Active and passive voice", content: "In an active sentence, the subject performs the action: The teacher praised the student. In a passive sentence, the subject receives the action: The student was praised by the teacher. Passive voice is useful when the action matters more than the actor." },
  { id: "grammar-conditionals", title: "Grammar: Conditional sentences", content: "Conditional sentences describe results and conditions. A zero conditional uses present forms for general truths: Water boils at 100 degrees Celsius. A first conditional uses will for likely future results: If it rains, we will stay home. Other forms discuss unlikely or unreal situations." },
  { id: "grammar-modal-verbs", title: "Grammar: Modal verbs", content: "Modal verbs such as can, may, must, should and will express ability, permission, obligation, advice or future intention. They are followed by a base verb: You should study. Modals change the tone of a statement without changing the main action." },
  { id: "grammar-question-forms", title: "Grammar: Question forms", content: "Yes or no questions usually place an auxiliary or modal before the subject: Do you learn English? Wh questions begin with a question word such as what, where, when, who, why or how. In formal English, the subject and auxiliary invert." },
  { id: "grammar-negative-sentences", title: "Grammar: Negative sentences", content: "Negatives use not, never, no or neither. With auxiliary or modal verbs, not follows the auxiliary: I do not know. Without an auxiliary, English usually adds do support: She does not play. Double negatives can change meaning in standard English." },
  { id: "grammar-imperatives", title: "Grammar: Imperative sentences", content: "An imperative gives a command, instruction, request or invitation. It uses the base verb and has an implied subject you: Open the book. Please makes a request softer. Negative imperatives use do not or never: Do not run." },
  { id: "grammar-exclamatives", title: "Grammar: Exclamative sentences", content: "Exclamative sentences express strong feeling and often begin with What or How. Examples include What a lovely day it is and How quickly you learned. They can be formal in writing and conversational in speech." },
  { id: "grammar-there-be", title: "Grammar: There be sentences", content: "There be sentences introduce or discuss existence. Example: There are three books on the table. The true subject comes after be, so the verb agrees with that noun: There is a book, but There are books." },
  { id: "grammar-dummy-it", title: "Grammar: Dummy it", content: "The pronoun it can fill the subject position when English needs a subject but has no real one. Example: It is raining. It can also introduce an evaluation with an infinitive: It is important to review your work." },
  { id: "grammar-personal-pronouns", title: "Grammar: Personal pronouns", content: "Personal pronouns replace nouns. I, you, he, she, it, we and they usually act as subjects, while me, you, him, her, it, us and them usually act as objects. Choosing the correct form depends on the pronoun's role." },
  { id: "grammar-pronoun-case", title: "Grammar: Pronoun case", content: "Subject pronouns perform actions: He helped me. Object pronouns receive actions: I helped him. Possessive pronouns show ownership: That book is mine. Using the wrong case is common in long noun phrases." },
  { id: "grammar-possessives", title: "Grammar: Possessive forms", content: "Possession is shown with possessive pronouns such as my and your, or with an apostrophe and s for nouns: the student's book. For plural nouns ending in s, add only an apostrophe: the students' books." },
  { id: "grammar-reflexive-pronouns", title: "Grammar: Reflexive pronouns", content: "Reflexive pronouns such as myself, yourself, himself, herself, itself, ourselves and themselves refer back to the subject. Example: She taught herself. Use them when the subject and object are the same person or thing." },
  { id: "grammar-demonstratives", title: "Grammar: Demonstratives", content: "Demonstratives point to nouns. This and that refer to singular nouns, while these and those refer to plural nouns. This and these usually suggest something near; that and those suggest something farther away in space or time." },
  { id: "grammar-quantifiers", title: "Grammar: Quantifiers", content: "Quantifiers show amount or number. Use many with countable plurals, much with uncountable nouns, and a lot of with either. Few and a few differ in tone: few suggests almost none, while a few suggests some." },
  { id: "grammar-determiners", title: "Grammar: Determiners", content: "Determiners come before nouns and include articles, demonstratives, possessives and quantifiers. Examples include the book, this book, my book and many books. A noun phrase can contain only a limited set of determiners." },
  { id: "grammar-comparatives-superlatives", title: "Grammar: Comparatives and superlatives", content: "Comparative adjectives compare two things and often use er or more: taller, more careful. Superlatives compare three or more things and use est or most: tallest, most careful. Irregular forms include good, better and best." },
  { id: "grammar-prepositions", title: "Grammar: Prepositions", content: "Prepositions show relationships such as place, time, direction and manner. Common examples are in, on, at, by, with, for, from and about. In the box, on the table and at 5 o clock each use a different relationship." },
  { id: "grammar-conjunctions", title: "Grammar: Conjunctions", content: "Conjunctions join words, phrases or clauses. Coordinating conjunctions such as and, but, or and so join equal parts. Subordinating conjunctions such as because, although and while introduce dependent clauses." },
  { id: "grammar-relative-clauses", title: "Grammar: Relative clauses", content: "Relative clauses add information about a noun. They often begin with who, whom, whose, which or that. The book that I borrowed is interesting. Defining clauses identify which thing is meant, while non-defining clauses add extra information." },
  { id: "grammar-reported-speech", title: "Grammar: Reported speech", content: "Reported speech repeats what someone said without quotation marks. Example: She said that she was tired. Tenses, pronouns and time expressions often shift back when the reporting verb is in the past." },
  { id: "grammar-commas", title: "Grammar: Commas", content: "Commas separate items in a list, set off introductory phrases and separate non-defining clauses. Example: After the meeting, we reviewed the plan, the budget and the timeline. They help readers group ideas." },
  { id: "grammar-semicolons-colons", title: "Grammar: Semicolons and colons", content: "A semicolon links closely related independent clauses: I finished the draft; you can review it. A colon introduces an explanation, list or quotation: We need three things: time, tools and evidence." },
  { id: "grammar-apostrophes", title: "Grammar: Apostrophes", content: "Apostrophes mark ownership and contractions. The cat's toy belongs to one cat; the cats' toys belong to several cats. Do not becomes don't in a contraction, and its as a possessive has no apostrophe." },
  { id: "grammar-quotation-marks", title: "Grammar: Quotation marks", content: "Quotation marks enclose direct speech and the titles of short works. Example: He said, 'I am ready.' In British and American styles, punctuation placement differs, so follow the style guide you are using." },
  { id: "grammar-parallel-structure", title: "Grammar: Parallel structure", content: "Parallel structure uses the same grammatical form for items in a list or comparison. Example: We value clarity, accuracy and fairness. Mixing forms, such as clarity and being accurate, can sound uneven." },
  { id: "grammar-topic-sentences", title: "Grammar: Topic sentences", content: "A topic sentence states the main idea of a paragraph. It usually appears near the beginning and helps the reader understand what the following sentences will support. Other sentences should explain, evidence or develop that idea." },
  { id: "grammar-cohesion-transitions", title: "Grammar: Cohesion and transitions", content: "Transitions show relationships between ideas. However signals contrast, therefore signals result, for example introduces evidence, and finally marks the end of a sequence. Use them sparingly and choose the relationship accurately." },
  { id: "grammar-paragraph-unity", title: "Grammar: Paragraph unity", content: "A unified paragraph develops one controlling idea. Sentences that introduce a new main idea usually belong in a new paragraph. Long paragraphs can be easier to read when divided at a clear change of focus." },
  { id: "grammar-summary-paraphrase", title: "Grammar: Summaries and paraphrases", content: "A summary condenses a source into its main points in your own words. A paraphrase restates a specific passage while keeping the meaning. Both should credit the original source when the ideas are not common knowledge." },
  { id: "grammar-register-tone", title: "Grammar: Register and tone", content: "Register is the level of formality in language. A formal report avoids slang and contractions, while a friendly message may use short sentences and everyday words. Good writing matches tone to audience and purpose." },
  { id: "grammar-sentence-variety", title: "Grammar: Sentence variety", content: "Varying sentence length and structure makes writing easier to follow. A short sentence can emphasise a key point, while a longer sentence can connect related ideas. Too much variety without clarity can confuse the reader." },
  { id: "grammar-run-ons-fragments", title: "Grammar: Fragments and run-on sentences", content: "A sentence fragment lacks a complete subject and verb or begins with a subordinator without an independent clause. A run-on sentence joins complete sentences without proper punctuation or a conjunction. Both can be fixed by separating or connecting clauses." },
  { id: "grammar-adverb-word-order", title: "Grammar: Adverb word order", content: "Adverbs of frequency often go before the main verb but after be: She often reads; She is often late. Manner adverbs usually follow the verb or object: He spoke clearly. Time and place details often come near the end." },
  { id: "grammar-phrasal-verbs", title: "Grammar: Phrasal verbs", content: "A phrasal verb combines a verb with a particle such as up, out or off. Examples include look up, find out and turn off. Some phrasal verbs are separable, so a short object can go between the verb and particle." },
  { id: "grammar-collocations", title: "Grammar: Collocations", content: "Collocations are words that naturally occur together, such as make a decision, take a risk and heavy rain. They are not always predictable from grammar alone. Learning common collocations makes language sound more natural." },
  { id: "grammar-hedging", title: "Grammar: Hedging", content: "Hedging uses careful language such as may, might, seems, suggests and in some cases. It shows appropriate uncertainty when evidence is limited. Clear writing still states what is known before describing what is uncertain." },
  { id: "grammar-defining-terms", title: "Grammar: Defining terms", content: "A good definition names the category a thing belongs to and the features that distinguish it from others. Example: A triangle is a polygon with three sides and three angles. Avoid using the word being defined inside its own definition." },
  { id: "grammar-explaining-processes", title: "Grammar: Explaining processes", content: "Process explanations list steps in a clear order. Signal words such as first, next, then and finally help readers follow the sequence. Each step should state both the action and its result." },
  { id: "grammar-comparing-contrasting", title: "Grammar: Comparing and contrasting", content: "Comparison shows similarities; contrast shows differences. Useful language includes similarly, in the same way, however, whereas and on the other hand. Make clear what is being compared and on which point." },

  /* -------------------------------- biology -------------------------------- */
  { id: "knowledge-cellular-respiration", title: "Knowledge: Cellular respiration", content: "Cellular respiration is the process cells use to release energy from food. In many organisms, oxygen helps convert glucose into carbon dioxide and water, producing ATP that powers cell activities. It happens in mitochondria and is different from photosynthesis, which stores energy." },
  { id: "knowledge-mitosis-meiosis", title: "Knowledge: Mitosis and meiosis", content: "Mitosis produces two genetically identical body cells for growth and repair. Meiosis produces sex cells with half the usual number of chromosomes, increasing genetic variation. Mistakes in these processes can lead to cells with abnormal chromosome numbers." },
  { id: "knowledge-genetics-patterns", title: "Knowledge: Inheritance patterns", content: "Dominant alleles can mask recessive alleles when both are present. Recessive traits usually appear only when an individual has two copies of the recessive allele. Punnett squares predict probabilities of inherited traits, not guaranteed outcomes for each child." },
  { id: "knowledge-evolution", title: "Knowledge: Evolution and natural selection", content: "Evolution is change in the inherited traits of populations over generations. Natural selection occurs when individuals with helpful heritable traits tend to survive and reproduce more successfully. Evolution acts on populations, not on individual organisms during their lifetimes." },
  { id: "knowledge-biodiversity", title: "Knowledge: Biodiversity", content: "Biodiversity is the variety of life at genetic, species and ecosystem levels. It supports services such as pollination, nutrient cycling, clean water and resilience to change. Habitat loss, pollution, overuse and climate change can reduce biodiversity." },
  { id: "knowledge-microorganisms", title: "Knowledge: Microorganisms", content: "Microorganisms include bacteria, archaea, many fungi, algae and protozoa. They are too small to see clearly without a microscope. Many are harmless or beneficial, helping decompose matter, make food and support ecosystems." },
  { id: "knowledge-viruses-bacteria", title: "Knowledge: Viruses and bacteria", content: "Bacteria are single-celled living organisms that can reproduce on their own. Viruses are much smaller and need host cells to reproduce. Antibiotics can treat many bacterial infections but do not work against viruses." },
  { id: "knowledge-vaccines-immunity", title: "Knowledge: Vaccines and immunity", content: "Vaccines train the immune system to recognise a pathogen without causing the full disease. They can reduce the risk of severe illness and help protect people who cannot be vaccinated. Immunity varies by vaccine, person and time." },
  { id: "knowledge-antibiotics-resistance", title: "Knowledge: Antibiotic resistance", content: "Antibiotic resistance occurs when bacteria change so medicines that once worked become less effective. Unnecessary or incomplete use of antibiotics can encourage resistant strains. Taking antibiotics only when prescribed helps slow resistance." },
  { id: "knowledge-plant-structures", title: "Knowledge: Plant structures", content: "Roots anchor plants and absorb water and minerals. Stems support leaves and transport materials, while leaves carry out much of photosynthesis. Flowers, fruits and seeds help plants reproduce and disperse." },
  { id: "knowledge-animal-adaptations", title: "Knowledge: Animal adaptations", content: "Adaptations are features that help organisms survive and reproduce in their environments. Camouflage, migrations, specialised beaks and nocturnal habits are examples. Adaptations arise over many generations through inherited variation and selection." },
  { id: "knowledge-human-senses", title: "Knowledge: Human senses", content: "The senses gather information about the environment. Eyes detect light, ears detect sound waves, the nose and tongue detect chemicals, and skin detects pressure, temperature and pain. The brain interprets these signals to guide behaviour." },

  /* ------------------------ chemistry, physics, earth ----------------------- */
  { id: "knowledge-chemical-bonds", title: "Knowledge: Chemical bonds", content: "Chemical bonds hold atoms together in molecules and crystals. Ionic bonds involve the transfer of electrons, covalent bonds involve sharing electrons, and metallic bonds involve delocalised electrons. Bond type helps determine properties such as melting point and conductivity." },
  { id: "knowledge-acids-bases", title: "Knowledge: Acids and bases", content: "Acids release hydrogen ions in water and have a pH below 7. Bases accept hydrogen ions or release hydroxide ions and have a pH above 7. A pH of 7 is neutral, and strong acids or bases require careful handling." },
  { id: "knowledge-solutions-mixtures", title: "Knowledge: Solutions and mixtures", content: "A solution is a homogeneous mixture in which a solute is dissolved in a solvent. Other mixtures, such as sand in water, are heterogeneous and can often be separated by filtering. Solubility can change with temperature." },
  { id: "knowledge-temperature-scales", title: "Knowledge: Temperature scales", content: "Celsius sets water's freezing point at 0 degrees and boiling point at 100 degrees at standard pressure. Fahrenheit uses 32 and 212 degrees for those points. Kelvin starts at absolute zero and is commonly used in science." },
  { id: "knowledge-electric-circuits", title: "Knowledge: Electric circuits", content: "An electric circuit needs a closed path for current to flow. Voltage provides the push, current is the flow of charge, and resistance limits the flow. Series circuits share one path; parallel circuits provide multiple paths." },
  { id: "knowledge-magnetism", title: "Knowledge: Magnetism", content: "Magnets create magnetic fields and attract certain materials such as iron. Every magnet has a north and south pole; like poles repel and unlike poles attract. Electric currents can produce magnetic fields, which is how electromagnets work." },
  { id: "knowledge-waves", title: "Knowledge: Waves", content: "A wave transfers energy without permanently moving the medium as a whole. In transverse waves, oscillations are perpendicular to travel direction; in longitudinal waves, they are parallel. Amplitude relates to energy and wavelength relates to frequency." },
  { id: "knowledge-electromagnetic-spectrum", title: "Knowledge: Electromagnetic spectrum", content: "The electromagnetic spectrum includes radio waves, microwaves, infrared, visible light, ultraviolet, X rays and gamma rays. All travel through space at the speed of light. Higher frequency waves generally carry more energy and can be more penetrating." },
  { id: "knowledge-nuclear-energy", title: "Knowledge: Nuclear energy", content: "Nuclear energy is released in reactions involving atomic nuclei. Fission splits heavy nuclei, while fusion combines light nuclei. Nuclear power produces large amounts of energy but requires careful management of radioactive materials." },
  { id: "knowledge-plate-tectonics", title: "Knowledge: Plate tectonics", content: "Earth's outer shell is divided into plates that move slowly over the mantle. Plates can diverge, converge or slide past one another. Their movement shapes mountains, earthquakes, volcanoes and ocean basins." },
  { id: "knowledge-earthquakes-volcanoes", title: "Knowledge: Earthquakes and volcanoes", content: "Earthquakes happen when stress on rocks causes sudden rupture and release of energy. Volcanoes form when magma reaches the surface. Both are common near plate boundaries, though some occur within plates." },
  { id: "knowledge-rock-cycle", title: "Knowledge: Rock cycle", content: "The rock cycle describes how igneous, sedimentary and metamorphic rocks change over time. Melting, cooling, weathering, erosion, compaction and heat drive the transformations. Rocks can follow different paths depending on conditions." },

  /* -------------------------------- astronomy ------------------------------ */
  { id: "knowledge-telescopes", title: "Knowledge: Telescopes", content: "Telescopes collect and focus light or other radiation from distant objects. Optical telescopes use lenses or mirrors, while radio telescopes detect radio waves. Larger collectors can detect fainter objects and reveal more detail." },
  { id: "knowledge-exoplanets", title: "Knowledge: Exoplanets", content: "Exoplanets are planets outside our solar system. Astronomers detect them by observing small dips in starlight, gravitational wobble or other subtle effects. Many known exoplanets differ greatly from the planets in our solar system." },
  { id: "knowledge-black-holes", title: "Knowledge: Black holes", content: "A black hole is a region where gravity is so strong that light cannot escape past its event horizon. Black holes can form when massive stars collapse. They can be detected by their effects on nearby stars and glowing material." },
  { id: "knowledge-big-bang", title: "Knowledge: Big bang model", content: "The big bang model describes the expansion of the universe from a very hot, dense early state. Evidence includes the expansion of galaxies, the cosmic microwave background and the abundance of light elements. It does not describe everything before that early state." },
  { id: "knowledge-space-probes", title: "Knowledge: Space probes", content: "Space probes are robotic spacecraft sent to study planets, moons, comets and other bodies. They can carry cameras, spectrometers and other instruments. Probes often provide closer and longer observations than telescopes from Earth." },
  { id: "knowledge-satellites-orbits", title: "Knowledge: Satellites and orbits", content: "Satellites orbit planets because their forward motion balances gravitational pull. Artificial satellites support communication, navigation, weather observation and research. Orbit height affects speed, coverage and how long a satellite remains useful." },
  { id: "knowledge-comets-asteroids", title: "Knowledge: Comets and asteroids", content: "Asteroids are rocky objects mostly found between Mars and Jupiter. Comets are icy objects that can develop tails when they approach the Sun. Both are remnants from the early solar system." },
  { id: "knowledge-stellar-life-cycle", title: "Knowledge: Stellar life cycle", content: "Stars form from clouds of gas and dust. A star like the Sun spends most of its life fusing hydrogen into helium, then expands into a red giant and later becomes a white dwarf. More massive stars can end in supernovae." },

  /* --------------------------------- math ---------------------------------- */
  { id: "knowledge-vectors", title: "Knowledge: Vectors", content: "A vector has both magnitude and direction. Vectors can represent forces, velocities and displacements. Adding vectors requires combining components, and a vector can be scaled by multiplying each component." },
  { id: "knowledge-matrices", title: "Knowledge: Matrices", content: "A matrix is a rectangular array of numbers arranged in rows and columns. Matrices can represent transformations and systems of linear equations. Matrix multiplication is not commutative, so order matters." },
  { id: "knowledge-logarithms", title: "Knowledge: Logarithms", content: "A logarithm answers the question of what exponent produces a given number. If 2 to the power of 3 equals 8, then log base 2 of 8 equals 3. Logarithms turn multiplication into addition and are useful for very large ranges." },
  { id: "knowledge-exponential-growth", title: "Knowledge: Exponential growth and decay", content: "Exponential growth occurs when a quantity increases by a fixed percentage or factor in each time period. Doubling is a common example. Exponential decay describes a quantity decreasing by a fixed factor, such as radioactive half life." },
  { id: "knowledge-polynomials", title: "Knowledge: Polynomials", content: "A polynomial is an expression made of terms with whole number powers of a variable. The highest power is its degree. Polynomials can be added, subtracted, multiplied, divided and factored." },
  { id: "knowledge-rational-functions", title: "Knowledge: Rational functions", content: "A rational function is a ratio of two polynomials. Its graph can have vertical asymptotes where the denominator is zero and horizontal or slant asymptotes that describe end behaviour. Values that make the denominator zero are excluded." },
  { id: "knowledge-conic-sections", title: "Knowledge: Conic sections", content: "Conic sections are curves formed by slicing a cone. They include circles, ellipses, parabolas and hyperbolas. Each can be described by an equation in two variables and has applications in orbits, optics and engineering." },
  { id: "knowledge-transformations-geometry", title: "Knowledge: Geometric transformations", content: "Geometric transformations move or change shapes. Translations slide, rotations turn, reflections flip and dilations resize. Rigid transformations preserve distances and angles, while dilations change size but preserve shape." },
  { id: "knowledge-bayes-theorem", title: "Knowledge: Bayes theorem", content: "Bayes theorem updates the probability of a hypothesis when new evidence is observed. It combines prior belief with the likelihood of the evidence under that hypothesis. Base rates matter, so a rare condition can still be unlikely after a positive test." },
  { id: "knowledge-sampling", title: "Knowledge: Sampling", content: "Sampling selects part of a population to learn about the whole. Random sampling helps reduce bias, while stratified sampling ensures groups are represented. Sample size affects precision, and how the sample is chosen affects reliability." },
  { id: "knowledge-hypothesis-testing", title: "Knowledge: Hypothesis testing", content: "A hypothesis test uses sample data to assess a claim about a population. It compares evidence against a null hypothesis and reports a p value or similar measure. A statistically significant result is not automatically practically important." },
  { id: "knowledge-graph-theory", title: "Knowledge: Graph theory", content: "Graph theory studies networks of nodes and edges. It is used for roads, social connections, computer networks and dependencies. A path visits connected nodes, a cycle returns to its start, and a tree connects nodes without cycles." },
  { id: "knowledge-prime-numbers", title: "Knowledge: Prime numbers", content: "A prime number is a whole number greater than one with exactly two factors: one and itself. Composite numbers have more than two factors. Prime factorisation expresses a number as a product of primes." },
  { id: "knowledge-modular-arithmetic", title: "Knowledge: Modular arithmetic", content: "Modular arithmetic works with remainders. In modulo 12, 15 is equivalent to 3 because both leave remainder 3. It is used in clocks, calendars, cryptography and number theory." },
  { id: "knowledge-boolean-algebra", title: "Knowledge: Boolean algebra", content: "Boolean algebra works with true and false values. The main operations are AND, OR and NOT. It underlies digital circuits, search filters and logical conditions in programming." },

  /* ---------------------------- computing and AI ---------------------------- */
  { id: "knowledge-operating-systems", title: "Knowledge: Operating systems", content: "An operating system manages computer hardware and provides services for programs. It handles processes, memory, files, devices and user interfaces. Examples include Windows, macOS, Linux, Android and iOS." },
  { id: "knowledge-file-systems", title: "Knowledge: File systems", content: "A file system organises how data is stored and retrieved on a device. It uses directories, file names and metadata such as size and modification time. Permissions control who can read or change files." },
  { id: "knowledge-databases", title: "Knowledge: Databases", content: "A database stores structured information for efficient retrieval and update. Relational databases use tables, rows and columns, while document databases store flexible records. Queries and indexes help find relevant data quickly." },
  { id: "knowledge-computer-networks", title: "Knowledge: Computer networks", content: "Computer networks connect devices so they can exchange data. Data is divided into packets that travel through routers and switches. Protocols define addressing, error handling and delivery rules." },
  { id: "knowledge-dns", title: "Knowledge: Domain name system", content: "The domain name system translates human readable names like example.com into IP addresses. This lets people use memorable names while computers route data numerically. DNS records are cached to make lookups faster." },
  { id: "knowledge-cloud-computing", title: "Knowledge: Cloud computing", content: "Cloud computing provides computing resources over a network on demand. Services can include storage, virtual machines, databases and software platforms. It can reduce upfront hardware costs but requires attention to security and pricing." },
  { id: "knowledge-encryption", title: "Knowledge: Encryption", content: "Encryption transforms data into a form that is hard to read without a key. It protects information in transit and at rest. Strong encryption depends on sound algorithms, secure keys and correct implementation." },
  { id: "knowledge-hashing", title: "Knowledge: Hashing", content: "A hash function maps data to a fixed size value called a hash. Cryptographic hashes are designed so small input changes produce very different outputs. They are used for integrity checks and password storage with added salt." },
  { id: "knowledge-phishing-security", title: "Knowledge: Phishing and security", content: "Phishing tries to trick people into revealing credentials or installing malware, often through convincing messages or fake websites. Check the sender, link destination and unexpected requests. Use multi factor authentication to reduce risk." },
  { id: "knowledge-version-control", title: "Knowledge: Version control", content: "Version control records changes to files so earlier states can be recovered and collaborators can work together. Git is a widely used distributed system. Commits, branches and merges organize development history." },
  { id: "knowledge-debugging", title: "Knowledge: Debugging", content: "Debugging is the process of finding and fixing errors in software. A good approach is to reproduce the problem, form a hypothesis, test it and change one thing at a time. Logs, tests and small examples help isolate causes." },
  { id: "knowledge-software-testing", title: "Knowledge: Software testing", content: "Software testing checks whether code behaves as expected. Unit tests examine small parts, integration tests check interactions, and end to end tests check complete workflows. Tests do not prove the absence of all bugs." },
  { id: "knowledge-api-basics", title: "Knowledge: APIs", content: "An API lets one program communicate with another through defined requests and responses. Web APIs often use HTTP methods such as GET, POST, PUT and DELETE. Clear documentation and stable interfaces make APIs easier to use." },
  { id: "knowledge-html-css-javascript", title: "Knowledge: HTML, CSS and JavaScript", content: "HTML gives web pages structure, CSS controls presentation, and JavaScript adds behaviour. These technologies work together in browsers. Semantic HTML improves accessibility and helps search tools understand content." },
  { id: "knowledge-data-structures", title: "Knowledge: Data structures", content: "Data structures organise data for particular operations. Arrays provide indexed access, linked lists allow flexible insertion, stacks and queues control order, and trees and graphs model hierarchies and networks. Choosing well affects performance." },
  { id: "knowledge-neural-networks", title: "Knowledge: Neural networks", content: "Neural networks are models made of layers of simple computational units that learn weights from data. Training adjusts those weights to reduce prediction error. Deep networks can learn complex patterns but need sufficient data and care." },
  { id: "knowledge-overfitting", title: "Knowledge: Overfitting", content: "Overfitting happens when a model learns noise or accidental patterns in training data and performs poorly on new data. Cross validation, more data, regularisation and simpler models can reduce it. Good training accuracy alone is not enough." },
  { id: "knowledge-tokenization-embeddings", title: "Knowledge: Tokenization and embeddings", content: "Tokenization splits text into units a model can process, such as words or subwords. Embeddings represent those units as vectors that capture learned relationships. Together they turn language into numerical inputs for a neural network." },

  /* ---------------------------- history and society ------------------------- */
  { id: "knowledge-ancient-greece", title: "Knowledge: Ancient Greece", content: "Ancient Greek city states developed distinctive political, artistic and philosophical traditions. Athens is known for democracy, philosophy and theatre, while Sparta emphasised military training. Greek ideas influenced later Roman, European and global culture." },
  { id: "knowledge-ancient-rome", title: "Knowledge: Ancient Rome", content: "Ancient Rome grew from a city state into a vast empire. Roman contributions include law, engineering, roads, aqueducts and Latin literature. The western empire ended in 476, while the eastern empire continued as Byzantium." },
  { id: "knowledge-middle-ages", title: "Knowledge: Middle Ages", content: "The Middle Ages in Europe followed the fall of the western Roman Empire and preceded the Renaissance. Feudal landholding, castles, trade towns and religious institutions shaped society. The period saw both conflict and advances in farming, architecture and learning." },
  { id: "knowledge-industrial-revolution", title: "Knowledge: Industrial Revolution", content: "The Industrial Revolution began in Britain in the late 18th century and spread widely. Mechanised production, steam power, factories and new transport changed work and cities. It raised output but also created labour, housing and environmental problems." },
  { id: "knowledge-french-revolution", title: "Knowledge: French Revolution", content: "The French Revolution began in 1789 and challenged monarchy, privilege and feudal structures in France. It produced declarations of rights, political upheaval and war. Its ideas influenced later movements while its violence remains debated." },
  { id: "knowledge-cold-war", title: "Knowledge: Cold War", content: "The Cold War was a long period of political and military tension after World War II, centred on the United States and the Soviet Union. It involved alliances, proxy wars, espionage and an arms race. It ended with the Soviet collapse in 1991." },
  { id: "knowledge-civil-rights-movements", title: "Knowledge: Civil rights movements", content: "Civil rights movements campaigned against discrimination and for equal treatment under law. The United States movement of the 1950s and 1960s challenged racial segregation and helped pass landmark legislation. Similar struggles occurred in many countries." },
  { id: "knowledge-forms-of-government", title: "Knowledge: Forms of government", content: "Governments differ in who holds power and how leaders are chosen. Democracies select leaders through elections and protect political participation. Authoritarian systems concentrate power and limit opposition. Many countries use mixed or federal systems." },
  { id: "knowledge-constitutions", title: "Knowledge: Constitutions", content: "A constitution sets out the basic rules, institutions and limits of government. It may define rights, powers, elections and the relationship between branches of state. Constitutions can be written in one document or developed across several sources." },
  { id: "knowledge-human-rights", title: "Knowledge: Human rights", content: "Human rights are basic freedoms and protections that apply to people because they are human. Common examples include rights to life, education, fair trial and freedom of expression. Different legal systems protect them through constitutions, laws and treaties." },
  { id: "knowledge-ethics", title: "Knowledge: Ethics", content: "Ethics examines what actions are right, fair and responsible. Consequentialist approaches focus on outcomes, duty based approaches focus on obligations, and virtue ethics focuses on character. Real decisions often involve competing values and uncertainty." },
  { id: "knowledge-logical-fallacies", title: "Knowledge: Logical fallacies", content: "A logical fallacy is a flaw in reasoning that weakens an argument. Examples include attacking the person instead of the claim, assuming what should be proved and treating a rare dramatic case as typical. Naming a fallacy does not by itself prove the opposite claim." },
  { id: "knowledge-rhetoric", title: "Knowledge: Rhetoric", content: "Rhetoric is the art of persuasive communication. Classical appeals include ethos, which builds credibility; pathos, which appeals to emotion; and logos, which uses evidence and reasoning. Ethical rhetoric respects the audience and avoids deception." },
  { id: "knowledge-mythology", title: "Knowledge: Mythology", content: "Myths are traditional stories that explain origins, natural events, social customs or human behaviour. They often include gods, heroes and symbolic events. Different cultures have distinct mythologies, and the same story can have many versions." },
  { id: "knowledge-archaeology", title: "Knowledge: Archaeology", content: "Archaeology studies past human societies through material remains such as tools, pottery, buildings and burials. Context is crucial because an object's location and associated finds affect its meaning. Ethical archaeology respects local communities and heritage laws." },

  /* ------------------------------ language and arts ------------------------- */
  { id: "knowledge-phonetics-phonology", title: "Knowledge: Phonetics and phonology", content: "Phonetics studies how speech sounds are produced and heard. Phonology studies how sounds function in a particular language. A sound may be physically similar yet distinguish meaning in one language and not another." },
  { id: "knowledge-morphology", title: "Knowledge: Morphology", content: "Morphology studies the structure of words. A word can contain a root, prefixes and suffixes, such as un helpful ness. Morphemes are the smallest units of meaning in a language." },
  { id: "knowledge-semantics-pragmatics", title: "Knowledge: Semantics and pragmatics", content: "Semantics studies the meaning of words and sentences. Pragmatics studies how context changes meaning in use, such as sarcasm, implication and politeness. The same sentence can express different intentions in different situations." },
  { id: "knowledge-dialects", title: "Knowledge: Dialects", content: "A dialect is a variety of a language associated with a region or social group. Dialects can differ in vocabulary, grammar and pronunciation. They are systematic and rule governed, not faulty versions of a standard language." },
  { id: "knowledge-color-theory", title: "Knowledge: Colour theory", content: "Colour theory studies how colours relate. Primary colours can be mixed to create secondary colours, while complementary colours sit opposite each other on a colour wheel. Artists use hue, saturation and value to create contrast and mood." },
  { id: "knowledge-visual-composition", title: "Knowledge: Visual composition", content: "Composition is the arrangement of elements within an image or design. Balance, contrast, rhythm, emphasis and unity help guide attention. Framing and negative space affect how a viewer reads the whole work." },
  { id: "knowledge-perspective-drawing", title: "Knowledge: Perspective drawing", content: "Perspective represents three dimensional space on a flat surface. Linear perspective uses converging lines and a horizon line to show depth. Atmospheric perspective uses lighter colour and reduced detail for distant objects." },
  { id: "knowledge-photography-basics", title: "Knowledge: Photography basics", content: "Photography controls light through aperture, shutter speed and sensitivity. A wide aperture lets in more light and reduces depth of field, while a fast shutter freezes motion. Composition and timing shape the final image." },
  { id: "knowledge-film-basics", title: "Knowledge: Film basics", content: "Film combines images, sound, editing and narrative. A shot records a continuous view, a scene collects shots in one place and time, and editing controls pace and continuity. Camera angle and sound shape meaning." },
  { id: "knowledge-theatre-basics", title: "Knowledge: Theatre basics", content: "Theatre is live performance in which actors, text, space and audience interact. Blocking is the planned movement of performers, while stage business is the small action that supports character. Live performance changes with each audience." },
  { id: "knowledge-architecture-styles", title: "Knowledge: Architectural styles", content: "Architectural styles reflect materials, technology, climate and culture. Classical architecture uses columns and symmetry, Gothic architecture uses pointed arches and flying buttresses, and modern architecture often favours simple forms and open plans. Buildings can combine styles." },
  { id: "knowledge-typography", title: "Knowledge: Typography", content: "Typography is the design and use of type. Typeface choice, size, spacing, line length and hierarchy affect readability and tone. Good typography helps readers scan and understand text without distraction." },

  /* ----------------------------- practical life ----------------------------- */
  { id: "knowledge-nutrition-basics", title: "Knowledge: Nutrition basics", content: "A balanced diet includes a variety of foods that provide energy, protein, fats, vitamins, minerals and fibre. Needs differ with age, activity and health. Nutrition advice should be adapted to individual circumstances and professional guidance when needed." },
  { id: "knowledge-exercise-basics", title: "Knowledge: Exercise basics", content: "Regular physical activity supports cardiovascular health, strength, mobility and mental wellbeing. A useful routine combines aerobic activity, strength work and flexibility. Increasing activity gradually reduces injury risk." },
  { id: "knowledge-sleep-hygiene", title: "Knowledge: Sleep hygiene", content: "Sleep hygiene means habits that support regular, restorative sleep. A consistent schedule, a dark quiet room, limited late caffeine and reduced screens before bed can help. Persistent sleep problems should be discussed with a professional." },
  { id: "knowledge-hygiene-basics", title: "Knowledge: Hygiene basics", content: "Good hygiene reduces the spread of germs. Washing hands with soap, cleaning food surfaces, keeping wounds covered and staying home when seriously ill protect others. Hygiene practices vary with setting but share the goal of preventing infection." },
  { id: "knowledge-emergency-preparedness", title: "Knowledge: Emergency preparedness", content: "Emergency preparedness means planning before disasters or accidents. Useful steps include keeping a contact list, storing water and basic supplies, knowing evacuation routes and learning local warning signals. Follow official instructions during an emergency." },
  { id: "knowledge-fire-safety", title: "Knowledge: Fire safety", content: "Fire safety includes smoke alarms, clear exits, safe cooking and careful use of electrical equipment. A small fire may be controlled with the correct extinguisher only if it is safe to do so. Otherwise, leave and call emergency services." },
  { id: "knowledge-road-safety", title: "Knowledge: Road safety", content: "Road safety depends on obeying speed limits, wearing seat belts, avoiding impaired driving and staying attentive. Pedestrians and cyclists benefit from visibility and predictable behaviour. Local traffic laws should always be followed." },
  { id: "knowledge-digital-wellbeing", title: "Knowledge: Digital wellbeing", content: "Digital wellbeing means using technology in ways that support health, relationships and work. Setting boundaries, taking breaks and curating notifications can reduce stress. Online privacy and security are part of healthy digital habits." },
  { id: "knowledge-note-taking", title: "Knowledge: Note taking", content: "Effective notes capture ideas in your own words, not just copied text. Organising by headings, questions and key terms makes later review easier. Reviewing notes soon after learning improves retention." },
  { id: "knowledge-time-management", title: "Knowledge: Time management", content: "Time management starts with identifying priorities and estimating how long tasks require. Breaking large work into smaller steps reduces procrastination. Calendars, task lists and regular review help keep commitments visible." },
  { id: "knowledge-goal-setting", title: "Knowledge: Goal setting", content: "Specific and measurable goals are easier to pursue than vague wishes. A useful goal states the outcome, a deadline and a way to track progress. Reviewing obstacles allows the plan to change while the purpose stays clear." },
  { id: "knowledge-active-listening", title: "Knowledge: Active listening", content: "Active listening means giving full attention, reflecting what you heard and asking clarifying questions. It helps reduce misunderstanding and shows respect. Avoid planning your reply while the other person is still speaking." },
  { id: "knowledge-public-speaking", title: "Knowledge: Public speaking", content: "Clear public speaking starts with a simple structure: opening, main points and conclusion. Knowing the audience, using short sentences and pausing at key moments improves clarity. Practice helps manage nerves." },
  { id: "knowledge-email-etiquette", title: "Knowledge: Email etiquette", content: "A clear email states the purpose, needed action and relevant context early. Use a specific subject line, address the recipient correctly and proofread before sending. Match formality to the relationship and organisation." },
  { id: "knowledge-teamwork", title: "Knowledge: Teamwork", content: "Effective teamwork combines clear roles, shared goals and open communication. Members should raise concerns early and record decisions. Respecting different strengths helps a group solve problems better than isolated work." },
  { id: "knowledge-conflict-resolution", title: "Knowledge: Conflict resolution", content: "Conflict resolution aims to address disagreement without damaging relationships. Start by stating the issue clearly, listening to each perspective and separating positions from interests. Agree on specific actions and follow up." },

  /* ------------------------ finance, consumer, home ------------------------- */
  { id: "knowledge-investing-basics", title: "Knowledge: Investing basics", content: "Investing puts money into assets such as shares, bonds or funds with the aim of growth or income. Returns are not guaranteed and values can fall as well as rise. Diversification, time horizon and risk tolerance are important considerations." },
  { id: "knowledge-insurance-basics", title: "Knowledge: Insurance basics", content: "Insurance transfers some financial risk to an insurer in exchange for premiums. Policies have limits, exclusions and deductibles that affect coverage. Reading the terms carefully matters before relying on a policy." },
  { id: "knowledge-consumer-rights", title: "Knowledge: Consumer rights", content: "Consumer rights vary by country but often include protection from misleading claims, unsafe products and unfair contract terms. Keep receipts and written records when disputing a purchase. Consumer agencies can explain local options." },
  { id: "knowledge-gardening-basics", title: "Knowledge: Gardening basics", content: "Successful gardening depends on climate, soil, light and water. Choosing plants suited to local conditions reduces effort and waste. Compost can improve soil structure, while mulch helps retain moisture and suppress weeds." },
  { id: "knowledge-recycling", title: "Knowledge: Recycling", content: "Recycling turns used materials into new products and can reduce demand for raw materials. Accepted items differ by local programme, so contamination from wrong items can cause problems. Reducing and reusing usually come before recycling in the waste hierarchy." },
  { id: "knowledge-energy-conservation", title: "Knowledge: Energy conservation", content: "Energy conservation reduces use through behaviour and efficient equipment. Insulation, efficient lighting, sensible heating settings and turning off unused devices can lower demand. Small changes add up when applied consistently." },
  { id: "knowledge-weather-safety", title: "Knowledge: Weather safety", content: "Weather safety means preparing for hazards such as storms, heat, cold, floods and high winds. Official warnings should guide decisions. During severe weather, follow local advice and avoid unnecessary travel." },
  { id: "knowledge-home-security", title: "Knowledge: Home security", content: "Home security combines good locks, lighting, awareness and habits such as closing windows and not advertising absences. Alarms and cameras can help but should be used lawfully and with respect for privacy. Simple routines often matter most." },
  { id: "knowledge-travel-planning", title: "Knowledge: Travel planning", content: "Travel planning includes documents, transport, accommodation, budget, health needs and local customs. Copies of important documents and a backup payment method help when plans change. Check entry rules and safety advice before departure." },
  { id: "knowledge-transport-safety", title: "Knowledge: Transport safety", content: "Transport safety includes following vehicle rules, using appropriate restraints and staying alert as a passenger or pedestrian. Public transport has its own etiquette and safety guidance. Planning ahead reduces rushed decisions." },
];
